            int r = r0 + rr;
            if (r > k) sP[(long)k * sliceH + rr] *= scale;     // becomes v[r]
            else if (r == k) sP[(long)k * sliceH + rr] = 1.0f; // v[k]=1 (temp; finalized to beta later)
